-- Esquema DAW UEA. Ejecutar en la base daw_uea.
CREATE TABLE IF NOT EXISTS rutas_aprendizaje (id_ruta SERIAL PRIMARY KEY,nombre VARCHAR(120) NOT NULL,descripcion TEXT NOT NULL,nivel VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS participantes (id_participante SERIAL PRIMARY KEY,nombre VARCHAR(120) NOT NULL,correo VARCHAR(150) NOT NULL UNIQUE,nivel VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS recursos (id_recurso SERIAL PRIMARY KEY,titulo VARCHAR(150) NOT NULL,descripcion TEXT NOT NULL,enlace TEXT NOT NULL,id_ruta INTEGER REFERENCES rutas_aprendizaje(id_ruta));
CREATE TABLE IF NOT EXISTS consultas (id_consulta SERIAL PRIMARY KEY,nombre VARCHAR(120) NOT NULL,correo VARCHAR(150) NOT NULL,tema VARCHAR(120) NOT NULL,mensaje TEXT NOT NULL,fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rutas_propuestas (id SERIAL PRIMARY KEY,titulo TEXT NOT NULL,nivel TEXT NOT NULL,objetivo TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS perfiles (id SERIAL PRIMARY KEY,alias TEXT NOT NULL,nivel TEXT NOT NULL,interes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recursos_propuestos (id SERIAL PRIMARY KEY,titulo TEXT NOT NULL,categoria TEXT NOT NULL,descripcion TEXT NOT NULL,enlace TEXT NOT NULL);

-- Semana 14: autenticación de usuarios con contraseñas hasheadas.
CREATE TABLE IF NOT EXISTS usuarios (id SERIAL PRIMARY KEY, usuario VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL);
